const r = $input.first().json;
const settings = $('Test Settings').first().json;
if (r.status !== 'passed' || r.test_type !== 'pipeline_smoke_test') throw new Error('Unexpected test response');
if (r.summary?.run_date !== settings.as_of_date) throw new Error('Wrong test date');
if (!Array.isArray(r.forecasts) || !r.forecasts.length || r.forecasts.length !== r.summary.total_skus) throw new Error('Missing forecasts');
if (new Set(r.forecasts.map(x => x.itemCode)).size !== r.forecasts.length) throw new Error('Duplicate products');
for (const row of r.forecasts) {
  if (typeof row.hybrid_forecast_15d !== 'number' || !Number.isFinite(row.hybrid_forecast_15d) || row.hybrid_forecast_15d < 0) throw new Error('Invalid demand');
}
return [{ json: { status: r.status, run_id: r.run_id, test_type: r.test_type, inventory_is_simulated: r.inventory_is_simulated, ...r.summary, total_forecast_quantity: r.forecasts.reduce((sum, row) => sum + row.hybrid_forecast_15d, 0), warnings: r.warnings, sample_forecasts: r.forecasts.slice(0, 5), sample_recommendations: r.recommendations.slice(0, 5) } }];
